List<Map<String, dynamic>> _syncIssueComments(
  GhSyncConfig c,
  _SyncIssueRef ref,
) {
  final resp = SyncHttpClient.get(
    '${c.baseUrl}/${ref.issueSeg}/comments?per_page=100',
