events=[]
for line in open(p):
    j=json.loads(line)
    if j.get('type')!='message': continue
    ts=j['timestamp']; m=j['message']; c=m.get('content')
    if isinstance(c,list):
        for b in c:
            if not isinstance(b,dict): continue
            if b.get('type')=='toolCall':
                events.append((ts,'call',b.get('name'),b.get('id'),b.get('arguments')))
            elif b.get('type')=='text' and m.get('role')=='toolResult':
                pass
    elif m.get('role')=='toolResult':
        txt='\n'.join(b.get('text','') for b in c if isinstance(b,dict) and b.get('type')=='text') if isinstance(c,list) else str(c)
        events.append((ts,'result',m.get('toolName'),m.get('toolCallId'),txt))
events.sort(key=lambda e:e[0])
print('events:',len(events))
# pair and save
import pickle
calls={}; seq=[]
for ts,kind,name,uid,payload in events:
    if kind=='call': calls[uid]=(ts,name,payload); seq.append(('call',ts,name,uid,payload))
    else:
        if uid in calls: seq.append(('result',ts,calls[uid][1],uid,payload))
with open('/tmp/replay/seq.pkl','wb') as f: pickle.dump(seq,f)
