#!/usr/bin/env python3
"""Replay the dev-write session transcript onto the current clean main checkout.

Simulates write/edit/read/bash effects using the transcript's own tool results
as ground truth for what actually applied. Emits final file states.
"""
import pickle, re, os, subprocess, sys, shutil

DART = '/tmp/dart/dart-sdk/bin/dart'
PAIRS = '/tmp/replay/pairs.pkl'
OUT = '/tmp/replay/out'
CUT = '2026-09-14T20:55'

pairs = pickle.load(open(PAIRS, 'rb'))

# Files where main's content is a valid fallback outside transcript-evidenced regions.
MAIN_OK = {
    'lib/src/agents/teammate_job.dart',
    'test/agents/teammate_job_test.dart',
    'test/cli/cli_dispatcher_test.dart',
    'test/integration/github_integration_test.dart',
    'lib/dmtools.dart',
    'lib/src/agents/agent_factory.dart',
    'lib/src/integrations/github/github_agent_tools.dart',
    'lib/src/integrations/github/github_client.dart',
    'crap4dart.yaml',
    # modified pre-session, transcript coverage partial -> main fallback flagged
    'lib/src/js/sync_tools/github_ci_sync_tools.dart',
}
# Created/rewritten by the lost earlier session; main content NOT valid.
NEW_FILES = {
    'lib/src/integrations/github_issue_tracker_tools.dart',
    'lib/src/integrations/github_ci_pr_tools.dart',
    'lib/src/integrations/github_client_issue_tools.dart',
    'test/integrations/github/github_issue_tracker_test.dart',
    'lib/src/agents/github_tracker_client.dart',
    # conflicted merge state -> main content NOT valid
    'lib/src/js/sync_tools/github_sync_tools.dart',
    'lib/src/js/sync_tools/github_issue_sync_tools.dart',
    'lib/src/js/sync_tools/github_pr_comments.dart',
}

ev = {}      # path -> {lineno: (text, src)}  src in {'tx','main'}
order = []   # first-touch order
log = []
regen_fixture = False
tmpfiles = {}  # /tmp file simulations

def touch(p):
    if p not in ev:
        ev[p] = {}
        order.append(p)
        if p in MAIN_OK and os.path.exists(p):
            with open(p, encoding='utf-8') as f:
                for i, line in enumerate(f.read().split('\n'), 1):
                    ev[p][i] = (line, 'main')
        elif p in MAIN_OK:
            log.append(f'WARN main_ok path missing on disk: {p}')

def seed_full(p, text):
    ev[p] = {}
    for i, line in enumerate(text.split('\n'), 1):
        ev[p][i] = (line, 'tx')

def coverage(p):
    d = ev.get(p, {})
    if not d:
        return 0, 0, 0
    lo, hi = min(d), max(d)
    missing = [n for n in range(lo, hi + 1) if n not in d]
    return lo, hi, len(missing)

def materialize(p):
    lo, hi, missing = coverage(p)
    if not d_size(p):
        return None
    if lo != 1:
        log.append(f'MATERIALIZE-GAP {p}: coverage starts at {lo}')
        return None
    if missing:
        log.append(f'MATERIALIZE-GAP {p}: {missing[0]}..{missing[-1]} ({len(missing)} missing lines)')
        return None
    return '\n'.join(ev[p][i][0] for i in range(1, hi + 1))

def d_size(p):
    return len(ev.get(p, {}))

NOTICE = re.compile(r'\n*\[\d+ more lines in file\. Use offset=\d+ to continue\.\]\s*$')

def parse_read(args, text):
    """Return (path, rows, eof) where rows is [(lineno, line)]."""
    path = args.get('path', '')
    offset = args.get('offset')
    limit = args.get('limit')
    hashline = args.get('hashline', False)
    # path selector support: :N, :A-B, :A+C, :raw combos
    m = re.search(r':(raw:)?(\d+)(?:-(\d+))?(\+\d+)?$', path)
    sel_offset = sel_end = None
    if m:
        path = path[:m.start()]
        sel_offset = int(m.group(2))
        if m.group(3):
            sel_end = int(m.group(3))
        elif m.group(4):
            sel_end = sel_offset + int(m.group(4)[1:]) - 1
    body = text
    eof = True
    nm = NOTICE.search(body)
    if nm:
        eof = False
        body = body[:nm.start()]
    rows = []
    if hashline or (body.startswith('[') and '#' in body.split('\n', 1)[0]):
        lines = body.split('\n')
        if lines and re.match(r'^\[[^\]]+#[0-9A-Fa-f]{4}\]$', lines[0]):
            lines = lines[1:]
        for ln in lines:
            if ln.startswith('…'):  # skipped-range separator
                continue
            m2 = re.match(r'^(\d+):(.*)$', ln)
            if m2:
                rows.append((int(m2.group(1)), m2.group(2)))
    else:
        content = body
        if content.endswith('\n'):
            content = content[:-1]
        start = offset if offset is not None else (sel_offset or 1)
        for i, ln in enumerate(content.split('\n'), start):
            rows.append((i, ln))
    return path, rows, eof, offset, limit

def apply_edit_exact(p, old, new):
    c = materialize(p)
    if c is None:
        log.append(f'EDIT-SKIP-UNMATERIALIZED {p}')
        return False
    n = c.count(old)
    if n != 1:
        log.append(f'EDIT-MISMATCH {p}: oldText count={n}')
        return False
    seed_full(p, c.replace(old, new, 1))
    return True

def apply_patch(p, patch):
    c = materialize(p)
    if c is None:
        log.append(f'PATCH-SKIP-UNMATERIALIZED {p}')
        return False
    lines = c.split('\n')
    N = len(lines)
    ops = []   # (kind, a, b, body)
    body = []
    cur = None
    for raw in patch.split('\n'):
        if re.match(r'^\[[^\]]+#[0-9A-Fa-f]{4}\]$', raw):
            continue
        m = re.match(r'^(SWAP|DEL|INS\.PRE|INS\.POST|INS\.HEAD|INS\.TAIL)(?:\s+(\d+)(?:\.=(\d+))?)?\s*:?\s*$', raw)
        if m:
            cur = (m.group(1), int(m.group(2) or 0), int(m.group(3) or m.group(2) or 0), [])
            ops.append(cur)
            continue
        if raw.startswith('+'):
            if cur is None:
                log.append(f'PATCH-BODY-NO-OP {p}')
                return False
            cur[3].append(raw[1:])
    out = []
    head = next((b for k, a, b2, b in ops if k == 'INS.HEAD'), None)
    tail = next((b for k, a, b2, b in ops if k == 'INS.TAIL'), None)
    core = [(k, a, b2, b) for k, a, b2, b in ops if k not in ('INS.HEAD', 'INS.TAIL')]
    if head: out.extend(head)
    pre = {a: b for k, a, b2, b in core if k == 'INS.PRE'}
    post = {a: b for k, a, b2, b in core if k == 'INS.POST'}
    swapdel = {}
    for k, a, b2, b in core:
        if k in ('SWAP', 'DEL'):
            swapdel[a] = (b2, b if k == 'SWAP' else None)
    i = 1
    while i <= N:
        if i in pre: out.extend(pre[i])
        if i in swapdel:
            end, bodyrows = swapdel[i]
            if bodyrows is not None: out.extend(bodyrows)
            i = end + 1
            if i in post:
                out.extend(post[i]); del post[i]
            continue
        out.append(lines[i - 1])
        if i in post: out.extend(post[i]); del post[i]
        i += 1
    if tail: out.extend(tail)
    seed_full(p, '\n'.join(out))
    return True

def run_dart_format(paths, root='.'):
    got = []
    for p in paths:
        if not p.endswith('.dart'):
            continue
        c = materialize(p)
        if c is None:
            log.append(f'FORMAT-SKIP-UNMATERIALIZED {p}')
            continue
        tmpd = '/tmp/replay/fmt'
        os.makedirs(os.path.dirname(tmpd + '/' + p), exist_ok=True)
        with open(tmpd + '/' + p, 'w', encoding='utf-8') as f:
            f.write(c + '\n')
        r = subprocess.run([DART, 'format', p], cwd=tmpd, capture_output=True, text=True)
        if r.returncode != 0:
            log.append(f'FORMAT-ERROR {p}: {r.stdout} {r.stderr}')
            continue
