/// `github_create_issue` — POST `/repos/{owner}/{repo}/issues`.
///
/// Java `GitHubIssues.createIssue` (#543): the repository resolves from
/// explicit parts or a composite `owner/repo` [key]; [body] optionally
/// sets the issue description (markdown).
Future<Map<String, dynamic>> createIssue(
  String? owner,
  String? repo,
  String title, {
  String? body,
  String? key,
}) async {
  final ref = resolveGhIssueRef(key, owner, repo, null);
  final response = await _http.post(
    'repos/${ref.owner}/${ref.repo}/issues',
    body: jsonEncode({
      'title': title,
      if (body != null && body.trim().isNotEmpty) 'body': body,
    }),
  );
  return jsonDecode(response) as Map<String, dynamic>;
}

/// `github_close_issue` — PATCH `/repos/{owner}/{repo}/issues/{number}`.
///
/// Java `GitHubIssues.closeIssue` (#543): accepts a composite [key].
Future<Map<String, dynamic>> closeIssue(
  String? owner,
  String? repo,
  int? number, {
  String? key,
}) async {
  final ref = resolveGhIssueRef(key, owner, repo, number);
  return _patchIssueState(ref, 'closed');
}

