/// Issue-family client methods — Java `GitHubIssues.java` (#543) parity.
///
/// Everything here hangs off [GithubClient] as a library extension so the
/// issue tools share the transport and the composite-key resolution without
/// growing the core client file.
part of 'github_client.dart';

/// Resolved GitHub issue reference — owner, repo, and issue/PR number.
///
/// Java `GitHubIssues.resolveIssueRef` (#543): a reference comes from
/// explicit `owner`/`repo`/`number` parts, a composite `owner/repo#123`
/// [key], or a bare/`gh-`-prefixed number against the configured defaults.
class GhIssueRef {
  /// Repository owner (e.g. `acme`).
  final String owner;

  /// Repository name (e.g. `widgets`).
  final String repo;

  /// Issue or pull-request number.
  final int number;

  /// Creates a resolved reference.
  const GhIssueRef(this.owner, this.repo, this.number);
}

/// Resolves a GitHub issue reference the Java way (see [GhIssueRef]).
///
/// Priority: explicit [owner]/[repo]/[number] parts, then the composite
/// [key] (`owner/repo#123`), then a bare or `gh-`-prefixed number resolved
/// against `GITHUB_REPOSITORY` or `SOURCE_GITHUB_WORKSPACE` /
/// `SOURCE_GITHUB_REPOSITORY`. Throws [FormatException] when nothing
/// resolves — Java surfaces the same failure as an IllegalArgumentException.
GhIssueRef resolveGhIssueRef(
  String? key,
  String? owner,
  String? repo,
  int? number,
) {
  final resolvedOwner = owner ?? _ghDefaultWorkspace();
  final resolvedRepo = repo ?? _ghDefaultRepository();
  if (number != null && resolvedOwner != null && resolvedRepo != null) {
    return GhIssueRef(resolvedOwner, resolvedRepo, number);
  }

  final trimmed = key?.trim() ?? '';
  final composite = RegExp(r'^(.+)/(.+)#(\d+)$').firstMatch(trimmed);
  if (composite != null) {
    return GhIssueRef(
      composite.group(1)!,
      composite.group(2)!,
      int.parse(composite.group(3)!),
    );
  }

  final bare = RegExp(r'^(?:gh-)?(\d+)$', caseSensitive: false)
      .firstMatch(trimmed);
  if (bare != null && resolvedOwner != null && resolvedRepo != null) {
    return GhIssueRef(resolvedOwner, resolvedRepo, int.parse(bare.group(1)!));
  }

  throw FormatException(
    'Cannot resolve GitHub issue reference "$key": need owner/repo parts, '
    'a composite owner/repo#123 key, or configured default repository.',
  );
}

String? _ghDefaultWorkspace() =>
    PropertyReader().getSourceGithubWorkspace() ??
    PropertyReader().githubWorkspace;

String? _ghDefaultRepository() {
  final reader = PropertyReader();
  final combined = reader.githubRepository;
  if (combined != null && combined.contains('/')) {
    final split = combined.split('/');
    if (split.length == 2) return split[1];
  }
  return reader.getSourceGithubRepository();
}

/// Coerces a loosely-typed issue number (int or numeric string) to an int.
int? _ghIntOrNull(dynamic value) {
  if (value == null) return null;
  if (value is int) return value;
  return int.tryParse(value.toString());
}

/// Issue read/write tools that extend the core [GithubClient].
extension GithubClientIssueTools on GithubClient {
  /// `github_search_issues` — GET `/search/issues` scoped to the repository.
  ///
  /// Java `GitHubIssues.searchIssues` (#543): the query is passed through
  /// verbatim and scoped with `repo:<ws>/<rp>` unless it already constrains
  /// a repository.
  Future<Map<String, dynamic>> searchIssues(
    String query,
    String? workspace,
    String? repository,
  ) async {
    final ws = workspace ?? _ghDefaultWorkspace();
    final rp = repository ?? _ghDefaultRepository();
    var scopedQuery = query.trim();
    if (!scopedQuery.contains('repo:') && ws != null && rp != null) {
      scopedQuery = 'repo:$ws/$rp $scopedQuery';
    }
    final body = await _http.get(
      'search/issues',
      queryParams: {'q': scopedQuery, 'per_page': '100'},
    );
    return jsonDecode(body) as Map<String, dynamic>;
  }

  /// `github_reopen_issue` — PATCH `repos/{o}/{r}/issues/{n}` state open.
  Future<Map<String, dynamic>> reopenIssue(
    String? owner,
    String? repo,
    int? number, {
    String? key,
  }) async {
    final ref = resolveGhIssueRef(key, owner, repo, number);
    return _patchIssueState(ref, 'open');
  }

  /// `github_assign_issue` — POST
  /// `repos/{o}/{r}/issues/{n}/assignees` with the single-element
  /// assignees array.
  Future<Map<String, dynamic>> assignIssue(
    String? owner,
    String? repo,
    int? number,
    String user, {
    String? key,
  }) async {
    final ref = resolveGhIssueRef(key, owner, repo, number);
    final response = await _http.post(
      'repos/${ref.owner}/${ref.repo}/issues/${ref.number}/assignees',
      body: jsonEncode({
        'assignees': [user],
      }),
    );
    return jsonDecode(response) as Map<String, dynamic>;
  }

  /// `github_move_issue_to_status` — close/reopen/label semantics.
  ///
  /// Java `GitHubIssues.moveIssueToStatus`: done-family statuses close,
  /// open-family statuses reopen, anything else is applied as a label.
  /// Returns the issue JSON for close/reopen, or the resulting label array
  /// for the label branch — Java serializes whichever raw payload the
  /// underlying call produced.
  Future<Object> moveIssueToStatus(
    String? owner,
    String? repo,
    int? number,
    String statusName, {
    String? key,
  }) async {
    if (statusName.trim().isEmpty) {
      throw ArgumentError('statusName is required');
    }
    final ref = resolveGhIssueRef(key, owner, repo, number);
    final s = statusName.trim().toLowerCase();
    if (_ghClosedStatuses.contains(s)) {
      return closeIssue(ref.owner, ref.repo, ref.number);
    }
    if (_ghOpenStatuses.contains(s)) {
      return reopenIssue(ref.owner, ref.repo, ref.number);
    }
    return addLabels(ref.owner, ref.repo, ref.number, [statusName.trim()]);
  }
}

/// Statuses that close the issue (Java parity).
const _ghClosedStatuses = {'done', 'closed', 'completed', 'resolved'};

/// Statuses that reopen the issue (Java parity).
const _ghOpenStatuses = {
  'open',
  'reopened',
  'reopen',
  'todo',
  'backlog',
  'in progress',
  'in_progress',
  'in review',
