/// CI-status, PR-activity, and release-asset client methods — the Java
/// `GitHub.java` `@MCPTool` set (#543) that the Dart client was missing.
///
/// Extension on [GithubClient] so the check-run/commit-status family shares
/// the transport without growing the core client file.
part of 'github_client.dart';

/// CI/PR/release-asset tools that extend the core [GithubClient].
extension GithubClientCiTools on GithubClient {
  /// `github_create_check_run` — POST `repos/{o}/{r}/check-runs`.
  ///
  /// Java `GitHub.createCheckRun` (#543): [title]/[summary]/[text] ride in
  /// the check-run `output` object; [status] is queued/in_progress while a
  /// [conclusion] marks the run complete.
  Future<Map<String, dynamic>> createCheckRun(
    String workspace,
    String repository,
    String name,
    String headSha, {
    String? status,
    String? title,
    String? summary,
    String? text,
    String? externalId,
  }) async {
    final payload = <String, dynamic>{
      'name': name,
      'head_sha': headSha,
      if (status != null) 'status': status,
      if (title != null || summary != null || text != null)
        'output': {
          if (title != null) 'title': title,
          if (summary != null) 'summary': summary,
          if (text != null) 'text': text,
        },
      if (externalId != null) 'external_id': externalId,
    };
    final response = await _http.post(
      'repos/$workspace/$repository/check-runs',
      body: jsonEncode(payload),
    );
    return jsonDecode(response) as Map<String, dynamic>;
  }

  /// `github_update_check_run` — PATCH
  /// `repos/{o}/{r}/check-runs/{checkRunId}`.
  ///
  /// Java `GitHub.updateCheckRun` (#543): [status] must be completed when a
  /// [conclusion] is sent; the output object is updated when any of
  /// [title]/[summary]/[text] are provided.
  Future<Map<String, dynamic>> updateCheckRun(
    String workspace,
    String repository,
    String checkRunId,
    String status, {
    String? conclusion,
    String? title,
    String? summary,
    String? text,
  }) async {
    final payload = <String, dynamic>{
      'status': status,
      if (conclusion != null) 'conclusion': conclusion,
      if (title != null || summary != null || text != null)
        'output': {
          if (title != null) 'title': title,
          if (summary != null) 'summary': summary,
          if (text != null) 'text': text,
        },
    };
    final response = await _http.patch(
      'repos/$workspace/$repository/check-runs/$checkRunId',
      body: jsonEncode(payload),
    );
    return jsonDecode(response) as Map<String, dynamic>;
  }

  /// `github_create_commit_status` — POST
  /// `repos/{o}/{r}/statuses/{sha}`.
  ///
  /// Java `GitHub.createCommitStatus` (#543): [state] is one of
  /// error/failure/pending/success; [context] names the check.
  Future<Map<String, dynamic>> createCommitStatus(
    String workspace,
    String repository,
    String sha,
    String state, {
    String? description,
    String? context,
    String? targetUrl,
  }) async {
    final payload = <String, dynamic>{
      'state': state,
      if (description != null) 'description': description,
      if (context != null) 'context': context,
      if (targetUrl != null) 'target_url': targetUrl,
    };
    final response = await _http.post(
      'repos/$workspace/$repository/statuses/$sha',
      body: jsonEncode(payload),
    );
    return jsonDecode(response) as Map<String, dynamic>;
  }

  /// `github_get_workflow_run` — GET
  /// `repos/{o}/{r}/actions/runs/{runId}`.
  Future<Map<String, dynamic>> getWorkflowRun(
    String workspace,
    String repository,
    String runId,
  ) async {
    final body = await _http.get(
      'repos/$workspace/$repository/actions/runs/$runId',
    );
    return jsonDecode(body) as Map<String, dynamic>;
  }

  /// `github_repository_dispatch` — POST
  /// `repos/{o}/{r}/dispatches`.
  ///
  /// Java `GitHub.repositoryDispatch` (#543): [clientPayload] is a JSON
  /// object serialized as the dispatch `client_payload`.
  Future<Map<String, dynamic>> repositoryDispatch(
    String workspace,
    String repository,
    String eventType,
    String? clientPayload,
  ) async {
    final payload = <String, dynamic>{
      'event_type': eventType,
      if (clientPayload != null && clientPayload.trim().isNotEmpty)
        'client_payload': jsonDecode(clientPayload) as Map<String, dynamic>,
    };
    final response = await _http.post(
      'repos/$workspace/$repository/dispatches',
      body: jsonEncode(payload),
    );
    return _decodeEmptyOk(response);
  }

  /// `github_update_pr_comment` — PATCH
  /// `repos/{o}/{r}/issues/comments/{commentId}` (PR comments are issue
  /// comments in the GitHub REST API).
  Future<Map<String, dynamic>> updatePullRequestComment(
    String workspace,
    String repository,
    String commentId,
    String text,
  ) async {
    final response = await _http.patch(
      'repos/$workspace/$repository/issues/comments/$commentId',
      body: jsonEncode({'body': text}),
    );
    return jsonDecode(response) as Map<String, dynamic>;
  }

  /// `github_delete_pr_comment` — DELETE
  /// `repos/{o}/{r}/issues/comments/{commentId}`.
  Future<Map<String, dynamic>> deletePullRequestComment(
    String workspace,
    String repository,
    String commentId,
  ) async {
    final body = await _http.delete(
      'repos/$workspace/$repository/issues/comments/$commentId',
    );
    return _decodeEmptyOk(body);
  }

  /// `github_get_pr_activities` — merged review + comment activity for a
  /// pull request, sorted by creation date (Java
  /// `GitHub.getPullRequestActivities` #543).
  Future<List<Map<String, dynamic>>> pullRequestActivities(
    String workspace,
    String repository,
    String pullRequestId,
  ) async {
    final activities = <Map<String, dynamic>>[];
    final reviews = await _http
        .get('repos/$workspace/$repository/pulls/$pullRequestId/reviews');
    activities.addAll(_decodeList(reviews)
        .map((r) => {...r, 'activity_type': 'review'}));
    final inline = await _http
        .get('repos/$workspace/$repository/pulls/$pullRequestId/comments');
    activities.addAll(_decodeList(inline)
        .map((c) => {...c, 'activity_type': 'inline_comment'}));
    final discussion = await _http
        .get('repos/$workspace/$repository/issues/$pullRequestId/comments');
    activities.addAll(_decodeList(discussion)
        .map((c) => {...c, 'activity_type': 'discussion_comment'}));
    DateTime _created(Map<String, dynamic> a) =>
        DateTime.tryParse('${a['created_at'] ?? ''}') ??
        DateTime.fromMillisecondsSinceEpoch(0);
    activities.sort((a, b) => _created(a).compareTo(_created(b)));
    return activities;
  }

  /// `github_list_prs_filtered` — GET
  /// `repos/{o}/{r}/pulls?state=<state>` filtered by a title regex.
  ///
  /// Java `GitHub.listPullRequestsFiltered` (#543): pages through the
  /// listing (100 per page) and keeps only the PRs whose title matches
  /// [titleRegex].
  Future<List<Map<String, dynamic>>> listPullRequestsFiltered(
    String workspace,
    String repository,
    String state,
    String titleRegex,
  ) async {
    final pattern = RegExp(titleRegex);
    final out = <Map<String, dynamic>>[];
    for (var page = 1;; page++) {
      final body = await _http.get(
        'repos/$workspace/$repository/pulls',
        queryParams: {
          'state': state,
          'sort': 'updated',
          'direction': 'desc',
          'per_page': '100',
          'page': '$page',
        },
      );
      final decoded = jsonDecode(body);
      if (decoded is! List) break;
      final prs = decoded.cast<Map<String, dynamic>>().toList();
      for (final pr in prs) {
        final title = '${pr['title'] ?? ''}';
        if (pattern.hasMatch(title)) out.add(pr);
      }
      if (prs.length < 100) break;
    }
    return out;
  }

  /// `github_list_release_assets` — GET
  /// `repos/{o}/{r}/releases/{releaseId}/assets`.
  Future<List<Map<String, dynamic>>> listReleaseAssets(
    String workspace,
    String repository,
    String releaseId,
  ) async {
    final body = await _http.get(
      'repos/$workspace/$repository/releases/$releaseId/assets',
    );
    return _decodeList(body);
  }

  /// `github_delete_release_asset` — DELETE
  /// `repos/{o}/{r}/releases/assets/{assetId}` (Java: void, surfaced as an
  /// empty-ok map).
  Future<Map<String, dynamic>> deleteReleaseAsset(
    String workspace,
    String repository,
    String assetId,
  ) async {
    final body = await _http.delete(
      'repos/$workspace/$repository/releases/assets/$assetId',
    );
    return _decodeEmptyOk(body);
  }

  /// `github_get_commits_from_branches` — commits on the branches matching
  /// [branchNameRegex], deduplicated by SHA (Java
  /// `GitHub.getCommitsFromBranches` #543).
  Future<List<Map<String, dynamic>>> getCommitsFromBranches(
    String workspace,
    String repository,
    String branchNameRegex,
    String? since,
  ) async {
    final pattern = RegExp(branchNameRegex);
    final branchesBody = await _http.get(
      'repos/$workspace/$repository/branches',
      queryParams: {'per_page': '100'},
    );
    final branches = jsonDecode(branchesBody);
    final out = <Map<String, dynamic>>[];
    final seenShas = <String>{};
    if (branches is! List) return out;
    for (final entry in branches) {
      if (entry is! Map<String, dynamic>) continue;
      final name = '${entry['name'] ?? ''}';
      if (!pattern.hasMatch(name)) continue;
      final commitsBody = await _http.get(
        'repos/$workspace/$repository/commits',
        queryParams: {'sha': name, if (since != null) 'since': since},
      );
      final decoded = jsonDecode(commitsBody);
      if (decoded is! List) continue;
      for (final commit in decoded.cast<Map<String, dynamic>>()) {
        final sha = '${commit['sha'] ?? ''}';
        if (sha.isEmpty || !seenShas.add(sha)) continue;
        out.add(commit);
      }
    }
    return out;
  }
}

