PropertyReader.setOverrides({
  'SOURCE_GITHUB_TOKEN': 'ghp_testtoken',
  'SOURCE_GITHUB_BASE_PATH': 'http://127.0.0.1:${fx.port}',
  'SOURCE_GITHUB_WORKSPACE': '',
  'SOURCE_GITHUB_REPOSITORY': '',
});
